
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gp86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gp86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.208905597788847e+00, -1.637697629072197e+00, -2.161262142825823e+00, -2.747071129385390e+00, -3.308447958053808e+00, -3.687714413539247e+00, -3.677194505094710e+00, -3.123117024467774e+00, -2.108741903393372e+00, -1.049645081534734e+00, -4.419490728718310e-01, -4.239555952666052e-01, -6.299850288054236e-01, -5.939764654672436e-01, -3.262899264243532e-01, -9.964964710699308e-02, -1.498610224514198e-02, -8.772012683399799e-04, -1.328457699501724e-05, -2.911024334309335e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


